import React, { useState, useEffect } from 'react';

// --- STYLES ---
const card = { background: 'white', padding: '24px', borderRadius: '12px', boxShadow: '0 4px 6px -1px rgba(0,0,0,0.1)', border: '1px solid #e2e8f0' };
const sectionTitle = { fontSize: '18px', fontWeight: 700, color: '#1e293b', marginBottom: '16px' };

function Analytics() {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch('http://localhost:5000/api/analytics')
      .then(res => res.json())
      .then(d => {
        setData(d);
        setLoading(false);
      })
      .catch(() => setLoading(false));
  }, []);

  if (loading) return <div style={{ padding: '40px', textAlign: 'center' }}>Loading Analytics...</div>;
  if (!data) return <div style={{ padding: '40px', color: 'red', textAlign: 'center' }}>Backend Connection Failed</div>;

  return (
    <div style={{ padding: '30px', background: '#f8fafc', minHeight: '100vh' }}>
      <h2 style={{ ...sectionTitle, fontSize: '24px' }}>Quality Analytics Dashboard</h2>

      {/* 📊 TOP INSIGHTS (Big Data Analytics) */}
      <div style={{ display: 'flex', gap: '20px', marginBottom: '20px' }}>
        <div style={{ ...card, flex: 1 }}>
          <h3 style={sectionTitle}>First Pass Yield (FPY)</h3>
          <h2 style={{ color: '#f59e0b', fontSize: '32px', margin: '10px 0' }}>{data.yieldRate || 0}%</h2>
          <p style={{ color: '#64748b', fontSize: '14px' }}>Target: 95.0%</p>
        </div>
        
        <div style={{ ...card, flex: 2 }}>
          <h3 style={sectionTitle}>Process Health</h3>
          <p style={{ marginBottom: '10px' }}>
            Current system is <strong>{data.yieldRate > 80 ? 'STABLE' : 'REQUIRES ATTENTION'}</strong>
          </p>
          <div style={{ width: '100%', background: '#e2e8f0', height: '12px', borderRadius: '6px', overflow: 'hidden' }}>
            <div style={{ width: `${data.yieldRate || 0}%`, background: '#10b981', height: '100%', transition: 'width 0.5s ease-in-out' }} />
          </div>
        </div>
      </div>

      {/* 🗂 KPI CARDS */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '20px', marginBottom: '30px' }}>
        {[
          { label: 'Total UAVs', val: data.total, color: '#1e293b' },
          { label: 'Passed', val: data.passed, color: '#10b981' },
          { label: 'Failed', val: data.failed, color: '#ef4444' },
          { label: 'In Progress', val: data.inProgress, color: '#f59e0b' }
        ].map(k => (
          <div key={k.label} style={{ ...card, textAlign: 'center', borderTop: `4px solid ${k.color}` }}>
            <h1 style={{ margin: 0, color: k.color }}>{k.val}</h1>
            <p style={{ margin: 0, fontWeight: 600, color: '#64748b' }}>{k.label}</p>
          </div>
        ))}
      </div>

      {/* 📈 ROOT CAUSE ANALYTICS */}
      <div style={card}>
        <h3 style={sectionTitle}>Defect Distribution (Bottleneck Analysis)</h3>
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '40px' }}>
          {(data.stageData || []).map((s, index) => (
            <div key={s.name} style={{ marginBottom: '5px' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '14px', marginBottom: '5px' }}>
                <span style={{ fontWeight: 500 }}>{s.name}</span>
                <span style={{ fontWeight: 700, color: s.defects > 5 ? '#ef4444' : '#1e293b' }}>{s.defects} Defects</span>
              </div>
              <div style={{ width: '100%', background: '#f1f5f9', height: '8px', borderRadius: '4px' }}>
                <div style={{ 
                  width: `${Math.min((s.defects / (data.total || 1)) * 100, 100)}%`, 
                  background: s.defects > 5 ? '#ef4444' : '#3b82f6', 
                  height: '100%', 
                  borderRadius: '4px' 
                }} />
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Note: The "UAV List" box code was removed from here */}
    </div>
  );
}

export default Analytics;
